-- Hand-written below: what the Prisma schema cannot express.

ALTER TABLE "reservation_table_rules" ADD CONSTRAINT "reservation_table_rules_party_check"
  CHECK ("min_party" BETWEEN 1 AND 100 AND ("max_party" IS NULL OR "max_party" BETWEEN "min_party" AND 100));

ALTER TABLE "reservation_combinations" ADD CONSTRAINT "reservation_combinations_name_check"
  CHECK (char_length("name") BETWEEN 1 AND 50);
ALTER TABLE "reservation_combinations" ADD CONSTRAINT "reservation_combinations_party_check"
  CHECK ("min_party" BETWEEN 1 AND 100 AND "max_party" BETWEEN "min_party" AND 100);
-- One live combination per name and location (archived ones keep their names).
CREATE UNIQUE INDEX "reservation_combinations_live_name_key"
  ON "reservation_combinations" ("tenant_id", "location_id", "name") WHERE "archived_at" IS NULL;

-- Minimal guest data (spec → GDPR). Email stored lower-case; one live guest per email per organization, so a guest's
-- history and retention clock span their visits; anonymised guests free the email.
ALTER TABLE "reservation_guests" ADD CONSTRAINT "reservation_guests_name_check"
  CHECK ("name" IS NULL OR char_length("name") BETWEEN 1 AND 100);
ALTER TABLE "reservation_guests" ADD CONSTRAINT "reservation_guests_email_check"
  CHECK ("email" IS NULL OR (char_length("email") BETWEEN 3 AND 254 AND "email" = lower("email") AND "email" LIKE '%_@_%'));
ALTER TABLE "reservation_guests" ADD CONSTRAINT "reservation_guests_phone_check"
  CHECK ("phone" IS NULL OR "phone" ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "reservation_guests" ADD CONSTRAINT "reservation_guests_locale_check"
  CHECK ("locale" ~ '^[a-z]{2}$');
CREATE UNIQUE INDEX "reservation_guests_live_email_key"
  ON "reservation_guests" ("tenant_id", "email") WHERE "email" IS NOT NULL AND "anonymised_at" IS NULL;

ALTER TABLE "reservations" ADD CONSTRAINT "reservations_number_check" CHECK (char_length("number") BETWEEN 1 AND 32);
ALTER TABLE "reservations" ADD CONSTRAINT "reservations_party_check" CHECK ("party_size" BETWEEN 1 AND 100);
ALTER TABLE "reservations" ADD CONSTRAINT "reservations_period_check" CHECK ("ends_at" > "starts_at");
ALTER TABLE "reservations" ADD CONSTRAINT "reservations_notes_check"
  CHECK (("guest_note" IS NULL OR char_length("guest_note") BETWEEN 1 AND 500)
     AND ("staff_note" IS NULL OR char_length("staff_note") BETWEEN 1 AND 500));

ALTER TABLE "reservation_status_changes" ADD CONSTRAINT "reservation_status_changes_actor_check"
  CHECK ("actor_kind" IN ('user', 'guest', 'system') AND ("actor_kind" = 'user') = ("actor_user_id" IS NOT NULL));

-- THE guarantee (ADR 0019): no table is in two blocking reservations whose periods overlap. '[)' ranges, so back-to-back
-- turns (18:00–20:00, 20:00–22:00) don't overlap. tenant_id is part of it: tenants never affect each other.
ALTER TABLE "reservation_tables" ADD CONSTRAINT "reservation_tables_period_check"
  CHECK (NOT isempty("period") AND lower_inc("period") AND NOT upper_inc("period")
     AND NOT lower_inf("period") AND NOT upper_inf("period"));
ALTER TABLE "reservation_tables" ADD CONSTRAINT "reservation_tables_no_overlap"
  EXCLUDE USING gist ("tenant_id" WITH =, "table_id" WITH =, "period" WITH &&) WHERE ("blocking");

-- Blocking statuses (ADR 0019 amendment 2026-11-01): pending, booked, arrived, seated. `requested` has no table rows.
-- period/blocking follow the reservation in the same statement, so they can never drift. SECURITY INVOKER (the
-- default): they run as durby_app under RLS and see only the tenant's rows.
CREATE FUNCTION reservations_sync_tables()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
BEGIN
  UPDATE reservation_tables
     SET period   = tstzrange(NEW.starts_at, NEW.ends_at, '[)'),
         blocking = NEW.status IN ('pending', 'booked', 'arrived', 'seated')
   WHERE tenant_id = NEW.tenant_id AND reservation_id = NEW.id;
  RETURN NEW;
END
$$;

CREATE TRIGGER reservations_sync_tables
  AFTER UPDATE OF starts_at, ends_at, status ON "reservations"
  FOR EACH ROW
  WHEN (OLD.starts_at IS DISTINCT FROM NEW.starts_at OR OLD.ends_at IS DISTINCT FROM NEW.ends_at
     OR OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION reservations_sync_tables();

-- Rows written by the api must match their reservation; this rejects a drift bug (23514).
CREATE FUNCTION reservation_tables_check()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
DECLARE
  r reservations%ROWTYPE;
BEGIN
  SELECT * INTO r FROM reservations WHERE tenant_id = NEW.tenant_id AND id = NEW.reservation_id;
  IF NEW.period IS DISTINCT FROM tstzrange(r.starts_at, r.ends_at, '[)')
     OR NEW.blocking IS DISTINCT FROM (r.status IN ('pending', 'booked', 'arrived', 'seated'))
     OR NEW.location_id IS DISTINCT FROM r.location_id THEN
    RAISE EXCEPTION 'reservation_tables row does not match reservation %', NEW.reservation_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

-- Depth 0 only: the sync trigger's own UPDATE sets matching values by construction.
CREATE TRIGGER reservation_tables_check
  BEFORE INSERT OR UPDATE ON "reservation_tables"
  FOR EACH ROW
  WHEN (pg_trigger_depth() = 0)
  EXECUTE FUNCTION reservation_tables_check();

-- History (CLAUDE.md rule 7): status changes are append-only like pos tickets (test/support/append-only.ts);
-- reservations and guests change but are never deleted (guests are anonymised). reservation_tables rows are deleted
-- when a booking moves tables; combination tables when a combination is edited.
CREATE FUNCTION reservations_append_only()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER reservation_status_changes_append_only
  BEFORE UPDATE OR DELETE OR TRUNCATE ON "reservation_status_changes"
  FOR EACH STATEMENT EXECUTE FUNCTION reservations_append_only();

REVOKE UPDATE, DELETE, TRUNCATE ON "reservation_status_changes" FROM durby_app;
REVOKE DELETE, TRUNCATE ON "reservations", "reservation_guests" FROM durby_app;

